pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "", ""); }
    function testRegression_property() public {
        c.mintToken(address(this), 10);
        uint256 initialTotalSupply = c.totalSupply();
        c.burn(1);
        uint256 finalTotalSupply = c.totalSupply();
        assertTrue(finalTotalSupply == initialTotalSupply - 1);
    }
}
